import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] ranges = new long[(int) n][2];
        for (int i = 0; i < ranges.length; i++) {
            for (int j = 0; j < ranges[i].length; j++) {
                ranges[i][j] = Long.parseLong(next());
            }
        }

        int count = (int) n;
        long[] keys = new long[count];
        for (int i = 0; i < count; i++) keys[i] = ranges[i][0] * 65536L + i;
        Arrays.sort(keys);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < count; i++) {
            long target = ranges[i][1] * 65536L;
            int lo = 0, hi = count;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (keys[mid] < target) lo = mid + 1;
                else hi = mid;
            }
            long result = (lo == count) ? -1 : (keys[lo] % 65536L) + 1;
            if (i > 0) out.append(" ");
            out.append(result);
        }
        System.out.println(out);
    }
}
